// AppendXVMBaseTx writes one XVMBaseTx object into b — every payload it points at first,
// then the object itself — and returns the object's offset.
inline std::int64_t AppendXVMBaseTx(zap::Builder& b, const XVMBaseTxInput& in) {
    std::vector<std::int64_t> outs_ptrs;
    outs_ptrs.reserve(in.Outs.size());
    for (const auto& elem : in.Outs) outs_ptrs.push_back(AppendTransferableOut(b, elem));
    std::vector<std::int64_t> ins_ptrs;
    ins_ptrs.reserve(in.Ins.size());
    for (const auto& elem : in.Ins) ins_ptrs.push_back(AppendTransferableIn(b, elem));
    std::int64_t outs_off = 0;
    if (!in.Outs.empty()) {
        auto lb = b.start_list(4);
        for (const auto off : outs_ptrs) lb.add_object_ptr(off);
        outs_off = lb.finish().first;
    }
    std::int64_t ins_off = 0;
    if (!in.Ins.empty()) {
        auto lb = b.start_list(4);
        for (const auto off : ins_ptrs) lb.add_object_ptr(off);
        ins_off = lb.finish().first;
    }
    auto ob = b.start_object(kXVMBaseTxSize);
    ob.set_u32(kXVMBaseTxNetworkIDOff, in.NetworkID);
    ob.set_bytes_fixed(kXVMBaseTxBlockchainIDOff, std::span<const std::uint8_t>(in.BlockchainID));
    ob.set_list(kXVMBaseTxOutsOff, outs_off, static_cast<std::int64_t>(in.Outs.size()));
    ob.set_list(kXVMBaseTxInsOff, ins_off, static_cast<std::int64_t>(in.Ins.size()));
    ob.set_bytes(kXVMBaseTxMemoOff, in.Memo);
    return ob.finish();
}

